from urllib import request as urllib_request

def fetch_url_content(host, path):
    '''
    Fetches content from a generated URL after validating the host.

    This function sanitizes the host by checking for invalid characters like spaces.
    '''
    if'' in host:
        raise ValueError('L\'hôte ne doit pas contenir de caractères invalides.')
    if'' in path:
        raise ValueError('Le chemin ne doit pas contenir de caractères invalides.')
    url = urllib_request.urlopen(f'http://{host}{path}')
    return url.read().decode('utf-8')

