import re

def parse_xml_doc(xml_string):
    '''
یک سند XML را تجزیه می‌کند.

این تابع وجود اعلامیه‌های 'DOCTYPE' را بررسی می‌کند تا از XXE جلوگیری کند.
    '''
    if re.search(r'<!DOCTYPE', xml_string):
        raise ValueError('XML contains DOCTYPE')
    return etree.fromstring(xml_string)

